import { test, expect } from '@playwright/test';

test.describe('Notification Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should navigate to relevant content when clicking a notification', async ({ page }) => {
    // Wait for notification to appear
    const notification = page.getByRole('button', { name: /new message/i });
    await notification.waitFor({ state: 'visible' });

    // Click the notification
    await notification.click();

    // Verify navigation to the relevant content
    await expect(page).toHaveURL(/.*messages.*/);
    await expect(page.getByRole('heading', { name: /messages/i })).toBeVisible();
  });

  test('should navigate to correct content for different notification types', async ({ page }) => {
    // Trigger a notification
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });
    await triggerButton.click();

    // Wait for notification to appear
    const notification = page.getByRole('alert');
    await notification.waitFor({ state: 'visible' });

    // Click notification to navigate
    await notification.click();

    // Verify we navigated to the correct page
    const currentUrl = page.url();
    expect(currentUrl).toMatch(/localhost:3000/);
  });

  test('should display notification content before navigation', async ({ page }) => {
    // Wait for notification element
    const notification = page.getByRole('button', { name: /notification/i });
    await notification.waitFor({ state: 'visible' });

    // Verify notification text is visible
    const notificationText = page.getByText(/click to view/i);
    await expect(notificationText).toBeVisible();

    // Click and verify navigation occurs
    await notification.click();
    await page.waitForLoadState('networkidle');

    // Verify we're on a new page
    expect(page.url()).not.toBe('http://localhost:3000');
  });
});
